from pathlib import Path

import pytest


def first_readable(names: list[str]) -> str:
    """Return the text of the first readable file in `names` under `notes`.

    Each name is resolved relative to the directory `notes` in the current
    working directory. Names are untrusted: any name that would resolve to a
    location outside `notes` (via `..`, an absolute path, a symlink pointing
    out, etc.) is treated as unreadable and skipped, as are names containing
    NUL bytes or empty names. Missing files, directories, and files that
    cannot be read or decoded as UTF-8 are also skipped. Returns the text of
    the first file that can be read, or "" if none can.
    """
    try:
        root = Path("notes").resolve()
    except (OSError, RuntimeError, ValueError):
        return ""
    for name in names:
        if not name or "\x00" in name:
            continue
        try:
            candidate = (root / name).resolve()
            if candidate == root or not candidate.is_relative_to(root):
                continue
            return candidate.read_text(encoding="utf-8")
        except (OSError, RuntimeError, ValueError):
            continue
    return ""


@pytest.fixture
def notes_dir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    monkeypatch.chdir(tmp_path)
    d = tmp_path / "notes"
    d.mkdir()
    return d


def test_returns_first_readable(notes_dir: Path) -> None:
    (notes_dir / "a.txt").write_text("alpha")
    (notes_dir / "b.txt").write_text("beta")
    assert first_readable(["a.txt", "b.txt"]) == "alpha"


def test_skips_missing(notes_dir: Path) -> None:
    (notes_dir / "b.txt").write_text("beta")
    assert first_readable(["missing.txt", "b.txt"]) == "beta"


def test_empty_inputs(notes_dir: Path) -> None:
    assert first_readable([]) == ""
    assert first_readable(["nope.txt"]) == ""


def test_empty_file_is_readable(notes_dir: Path) -> None:
    (notes_dir / "empty.txt").write_text("")
    (notes_dir / "b.txt").write_text("beta")
    assert first_readable(["empty.txt", "b.txt"]) == ""


def test_directory_name_skipped(notes_dir: Path) -> None:
    (notes_dir / "sub").mkdir()
    (notes_dir / "b.txt").write_text("beta")
    assert first_readable(["sub", "b.txt"]) == "beta"
    assert first_readable(["sub"]) == ""


def test_empty_and_dot_names_skipped(notes_dir: Path) -> None:
    (notes_dir / "b.txt").write_text("beta")
    assert first_readable(["", ".", "b.txt"]) == "beta"
    assert first_readable(["", "."]) == ""


def test_subdirectory_file_allowed(notes_dir: Path) -> None:
    (notes_dir / "sub").mkdir()
    (notes_dir / "sub" / "c.txt").write_text("gamma")
    assert first_readable(["sub/c.txt"]) == "gamma"


def test_parent_traversal_rejected(notes_dir: Path) -> None:
    (notes_dir.parent / "secret.txt").write_text("secret")
    assert first_readable(["../secret.txt"]) == ""
    assert first_readable(["sub/../../secret.txt"]) == ""


def test_traversal_skipped_then_next_name_used(notes_dir: Path) -> None:
    (notes_dir.parent / "secret.txt").write_text("secret")
    (notes_dir / "a.txt").write_text("alpha")
    assert first_readable(["../secret.txt", "a.txt"]) == "alpha"


def test_absolute_path_rejected(notes_dir: Path) -> None:
    secret = notes_dir.parent / "secret.txt"
    secret.write_text("secret")
    assert first_readable([str(secret)]) == ""


def test_absolute_path_to_file_inside_notes_rejected_or_allowed_safely(
    notes_dir: Path,
) -> None:
    # An absolute path must never reach outside notes; a name that is
    # absolute and outside must be skipped in favor of later names.
    secret = notes_dir.parent / "secret.txt"
    secret.write_text("secret")
    (notes_dir / "a.txt").write_text("alpha")
    assert first_readable([str(secret), "a.txt"]) == "alpha"


def test_sibling_directory_with_notes_prefix_rejected(notes_dir: Path) -> None:
    sibling = notes_dir.parent / "notes_evil"
    sibling.mkdir()
    (sibling / "x.txt").write_text("evil")
    assert first_readable(["../notes_evil/x.txt"]) == ""


def test_symlink_escape_rejected(notes_dir: Path) -> None:
    outside = notes_dir.parent / "outside.txt"
    outside.write_text("outside")
    link = notes_dir / "link.txt"
    try:
        link.symlink_to(outside)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert first_readable(["link.txt"]) == ""


def test_symlinked_directory_escape_rejected(notes_dir: Path) -> None:
    outside_dir = notes_dir.parent / "outside_dir"
    outside_dir.mkdir()
    (outside_dir / "x.txt").write_text("outside")
    try:
        (notes_dir / "d").symlink_to(outside_dir, target_is_directory=True)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert first_readable(["d/x.txt"]) == ""


def test_symlink_inside_notes_allowed(notes_dir: Path) -> None:
    (notes_dir / "real.txt").write_text("real")
    try:
        (notes_dir / "alias.txt").symlink_to(notes_dir / "real.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert first_readable(["alias.txt"]) == "real"


def test_nul_byte_name_skipped(notes_dir: Path) -> None:
    (notes_dir / "a.txt").write_text("alpha")
    assert first_readable(["a.txt\x00.png"]) == ""
    assert first_readable(["bad\x00name", "a.txt"]) == "alpha"


def test_undecodable_file_skipped(notes_dir: Path) -> None:
    (notes_dir / "bin.dat").write_bytes(b"\xff\xfe\x00\x80")
    (notes_dir / "a.txt").write_text("alpha")
    assert first_readable(["bin.dat", "a.txt"]) == "alpha"


def test_unreadable_permissions_skipped(notes_dir: Path) -> None:
    locked = notes_dir / "locked.txt"
    locked.write_text("hidden")
    locked.chmod(0o000)
    try:
        try:
            locked.read_text()
        except OSError:
            pass
        else:
            pytest.skip("permissions not enforced (e.g. running as root)")
        (notes_dir / "a.txt").write_text("alpha")
        assert first_readable(["locked.txt", "a.txt"]) == "alpha"
    finally:
        locked.chmod(0o644)


def test_missing_notes_directory(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    assert first_readable(["a.txt"]) == ""
